:root {
    --color-dark: #2F4F4F;
    --color-accent: #C5A059;
    --color-light: #F4F1EA;
    --font-heading: 'Playfair Display', serif;
    --font-body: 'Lato', sans-serif;
    --space-sm: 1rem;
    --space-md: 2rem;
    --space-lg: 4rem;
    --radius: 4px;
    --max-width: 65ch;
}

html {
    overflow-x: clip;
    scroll-behavior: smooth;
    background-color: var(--color-light);
}

body {
    margin: 0;
    font-family: var(--font-body);
    color: var(--color-dark);
    line-height: 1.6;
    font-size: 1.125rem;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    color: var(--color-dark);
    margin: 0 0 1rem;
    line-height: 1.2;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 3vw, 3rem); }
h3 { font-size: clamp(1.5rem, 2vw, 2rem); }

.skip-link {
    position: absolute;
    left: -10000px;
    top: auto;
    width: 1px;
    height: 1px;
    overflow: hidden;
}

.skip-link:focus {
    position: static;
    width: auto;
    height: auto;
    padding: 1rem;
    background: var(--color-accent);
    color: white;
}

header {
    padding: var(--space-md);
    background: white;
    border-bottom: 1px solid var(--color-accent);
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
}

.logo { font-family: var(--font-heading); font-weight: 700; font-size: 1.5rem; }

nav ul { display: flex; list-style: none; gap: var(--space-md); margin: 0; padding: 0; }
nav a { text-decoration: none; color: var(--color-dark); font-weight: 700; padding: 0.5rem; border-radius: var(--radius); }
nav a:hover, nav a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

section { padding: var(--space-lg) var(--space-md); max-width: 1200px; margin: 0 auto; }

.hero { background: var(--color-light); text-align: center; }
.hero-feature { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: var(--space-lg); margin-top: var(--space-lg); }
.hero img { width: 100%; height: auto; object-fit: contain; }

.feature-split { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-lg); background: white; }
.media-container img { width: 100%; object-fit: contain; }

.grid-section { background: var(--color-light); }
.main-feature { margin-bottom: var(--space-lg); }
.secondary-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: var(--space-md); }
.card { background: white; padding: var(--space-md); border-radius: var(--radius); }

.highlight-band { display: flex; align-items: center; gap: var(--space-lg); background: var(--color-dark); color: white; }
.highlight-band h2, .highlight-band p { color: white; }

.premium-showcase { background: white; }
.showcase-content { display: grid; grid-template-columns: 1fr 2fr; gap: var(--space-lg); }

.full-bleed-band { background: var(--color-accent); color: white; text-align: center; }
.full-bleed-band img { max-width: 400px; margin: var(--space-md) auto; }

footer { background: var(--color-dark); color: white; padding: var(--space-lg); text-align: center; }

img { max-width: 100%; height: auto; }

html.js .reveal { 
    opacity: 0; 
    transform: translateY(24px); 
    transition: opacity 0.8s ease-out, transform 0.8s ease-out; 
}
html.js .reveal.active { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
    html.js .reveal { transition: none; }
}

@media (max-width: 768px) {
    .hero-feature, .feature-split, .showcase-content { grid-template-columns: 1fr; }
    .nav-toggle { display: block; }
}

button:focus-visible { outline: 2px solid var(--color-accent); }

